nce","strength":"direct","criterion":{"label":"Playing with friends","decisionDomains":["play","relationships"]}},{"optionId":"e","attributeKey":"play.session.preference","value":"novelty","statement":"You said an hour of play feels well spent when it is something new to try.","scope":"an hour of free play","kind":"preference","strength":"direct","criterion":{"label":"Something new to try","decisionDomains":["play","hobbies"]}}]}'::jsonb)
